// scheduleDefinition unmarshals the deployment definition embedded in a scheduled action.
func scheduleDefinition(s apitype.ScheduledAction) apitype.ScheduledDeploymentDefinition {
	var def apitype.ScheduledDeploymentDefinition
	if len(s.Definition) > 0 {
		_ = json.Unmarshal(s.Definition, &def)
