// toScheduleSummary converts a scheduled action into its flattened summary form,
// inferring the type, settings, and schedule from the action's definition.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	def := scheduleDefinition(s)
	var op apitype.PulumiOperation
	var opts *apitype.OperationContextOptions
	if def.Request != nil {
		op = def.Request.Op
		if def.Request.Operation != nil {
			opts = def.Request.Operation.Options
		}
	}

	schedule := s.ScheduleCron
	if schedule == "" {
		schedule = s.ScheduleOnce
	}

	var typ, settings string
	switch {
	case op == apitype.Destroy && s.ScheduleOnce != "":
		typ = scheduleKindTTL
		schedule = "Once"
		settings = "destroy"
		if opts != nil && opts.DeleteAfterDestroy {
			settings = "destroy + delete stack"
		}
	case op == apitype.DetectDrift:
		typ = scheduleKindDrift
		settings = "detect"
	default:
		typ = scheduleKindRaw
		settings = "pulumi " + string(op)
	}

	summary := scheduleSummary{
		ID:       s.ID,
		Type:     typ,
		Settings: settings,
		Schedule: schedule,
		NextRun:  s.NextExecution,
		Created:  s.Created,
	}
	if s.LastExecuted != nil {
		summary.LastRun = *s.LastExecuted
	}
	return summary
}

